import sys
input = sys.stdin.readline

def bit_add(t, i, x):
    n = len(t) - 1
    while i <= n:
        t[i] += x
        i += i & -i

def bit_sum(t, i):
    s = 0
    while i > 0:
        s += t[i]
        i -= i & -i
    return s

n, q = map(int, input().split())
ops = [list(map(int, input().split())) for _ in range(q)]

state = [1] * (n + 1)
t = [0] * (n + 1)
for i in range(1, n + 1):
    bit_add(t, i, 1)
out = []
for kind, i in ops:
    if kind == 1:
        if state[i] == 1:
            state[i] = 0
            bit_add(t, i, -1)
    elif kind == 2:
        if state[i] == 0:
            state[i] = 1
            bit_add(t, i, 1)
    else:
        out.append(bit_sum(t, i - 1))
print(*out)

